// The tree is generated by home/desktop/hyprland/vicinae-data.nix from the
// same catalog/ that drives Plasma's menu (home/desktop/apps-menu.nix)
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

export const DATA_PATH = path.join(os.homedir(), ".local/share/annixion/kill-chain.json");

export interface Snippet {
	label: string;
	command: string;
}

export interface Tool {
	id: string;
	name: string;
	genericName: string | null;
	comment: string | null;
	description: string | null;
	docs: string | null;
	snippets: Snippet[];
	markClass: string;
	icon: string | null;
	exec: string;
}

export interface TreeNode {
	id: string;
	label: string;
	markClass: string;
	icon: string | null;
	children: TreeNode[];
	tools: Tool[];
}

export interface KillChainData {
	phases: TreeNode[];
	other: TreeNode[];
}

export function loadData(): KillChainData {
	const raw = fs.readFileSync(DATA_PATH, "utf8");
	return JSON.parse(raw) as KillChainData;
}
